///   9. `[]` system_program
///   10. `[]` rent
///   11. `[]` sysvar_instructions
///   12. `[]` recent_slothashes
///   13. `[]` jellybean_event_authority
#[derive(Clone, Debug)]
pub struct DrawJellybeanCpiBuilder<'a, 'b> {
    instruction: Box<DrawJellybeanCpiBuilderInstruction<'a, 'b>>,
}

impl<'a, 'b> DrawJellybeanCpiBuilder<'a, 'b> {
    pub fn new(program: &'b solana_account_info::AccountInfo<'a>) -> Self {
        let instruction = Box::new(DrawJellybeanCpiBuilderInstruction {
            __program: program,
            gumball_guard: None,
            jellybean_machine_program: None,
            jellybean_machine: None,
            jellybean_machine_authority_pda: None,
            payer: None,
            buyer: None,
            unclaimed_prizes: None,
            print_fee_account: None,
            spl_token_program: None,
            system_program: None,
            rent: None,
            sysvar_instructions: None,
            recent_slothashes: None,
            jellybean_event_authority: None,
            mint_args: None,
            group: None,
            __remaining_accounts: Vec::new(),
        });
        Self { instruction }
    }
    /// Gumball Guard account.
    #[inline(always)]
    pub fn gumball_guard(
        &mut self,
        gumball_guard: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.gumball_guard = Some(gumball_guard);
        self
    }
    /// Jellybean Machine program account.
    ///
    #[inline(always)]
    pub fn jellybean_machine_program(
        &mut self,
        jellybean_machine_program: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.jellybean_machine_program = Some(jellybean_machine_program);
        self
    }
    /// Jellybean machine account.
    #[inline(always)]
    pub fn jellybean_machine(
        &mut self,
        jellybean_machine: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.jellybean_machine = Some(jellybean_machine);
        self
    }
    #[inline(always)]
    pub fn jellybean_machine_authority_pda(
        &mut self,
        jellybean_machine_authority_pda: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.jellybean_machine_authority_pda = Some(jellybean_machine_authority_pda);
        self
    }
    /// Payer for the mint (SOL) fees.
    #[inline(always)]
    pub fn payer(&mut self, payer: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.payer = Some(payer);
        self
    }
    /// Minter account for validation and non-SOL fees.
    #[inline(always)]
    pub fn buyer(&mut self, buyer: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.buyer = Some(buyer);
        self
    }
    #[inline(always)]
    pub fn unclaimed_prizes(
        &mut self,
        unclaimed_prizes: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.unclaimed_prizes = Some(unclaimed_prizes);
        self
    }
    /// `[optional account]`
    /// Print fee account. Required if the jellybean machine has a print fee config.
    #[inline(always)]
    pub fn print_fee_account(
        &mut self,
        print_fee_account: Option<&'b solana_account_info::AccountInfo<'a>>,
    ) -> &mut Self {
        self.instruction.print_fee_account = print_fee_account;
        self
    }
    /// SPL Token program.
    #[inline(always)]
    pub fn spl_token_program(
        &mut self,
        spl_token_program: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.spl_token_program = Some(spl_token_program);
        self
    }
    /// System program.
    #[inline(always)]
    pub fn system_program(
        &mut self,
        system_program: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.system_program = Some(system_program);
        self
    }
    /// Rent.
    #[inline(always)]
    pub fn rent(&mut self, rent: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.rent = Some(rent);
        self
    }
    /// Instructions sysvar account.
    ///
    #[inline(always)]
    pub fn sysvar_instructions(
        &mut self,
        sysvar_instructions: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.sysvar_instructions = Some(sysvar_instructions);
        self
    }
    /// SlotHashes sysvar cluster data.
    ///
    #[inline(always)]
    pub fn recent_slothashes(
        &mut self,
        recent_slothashes: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.recent_slothashes = Some(recent_slothashes);
        self
    }
    #[inline(always)]
    pub fn jellybean_event_authority(
        &mut self,
        jellybean_event_authority: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.jellybean_event_authority = Some(jellybean_event_authority);
        self
    }
    #[inline(always)]
    pub fn mint_args(&mut self, mint_args: Vec<u8>) -> &mut Self {
        self.instruction.mint_args = Some(mint_args);
        self
    }
    /// `[optional argument]`
    #[inline(always)]
    pub fn group(&mut self, group: String) -> &mut Self {
        self.instruction.group = Some(group);
        self
    }
    /// Add an additional account to the instruction.
    #[inline(always)]
    pub fn add_remaining_account(
        &mut self,
        account: &'b solana_account_info::AccountInfo<'a>,
        is_writable: bool,
        is_signer: bool,
    ) -> &mut Self {
        self.instruction
            .__remaining_accounts
            .push((account, is_writable, is_signer));
        self
    }
    /// Add additional accounts to the instruction.
    ///
    /// Each account is represented by a tuple of the `AccountInfo`, a `bool` indicating whether the account is writable or not,
    /// and a `bool` indicating whether the account is a signer or not.
    #[inline(always)]
    pub fn add_remaining_accounts(
        &mut self,
        accounts: &[(&'b solana_account_info::AccountInfo<'a>, bool, bool)],
    ) -> &mut Self {
        self.instruction
            .__remaining_accounts
            .extend_from_slice(accounts);
        self
    }
    #[inline(always)]
    pub fn invoke(&self) -> solana_program_error::ProgramResult {
        self.invoke_signed(&[])
    }
    #[allow(clippy::clone_on_copy)]
    #[allow(clippy::vec_init_then_push)]
    pub fn invoke_signed(&self, signers_seeds: &[&[&[u8]]]) -> solana_program_error::ProgramResult {
        let args = DrawJellybeanInstructionArgs {
            mint_args: self
                .instruction
                .mint_args
                .clone()
                .expect("mint_args is not set"),
            group: self.instruction.group.clone(),
        };
        let instruction = DrawJellybeanCpi {
            __program: self.instruction.__program,

            gumball_guard: self
                .instruction
                .gumball_guard
                .expect("gumball_guard is not set"),

            jellybean_machine_program: self
                .instruction
                .jellybean_machine_program
                .expect("jellybean_machine_program is not set"),

            jellybean_machine: self
                .instruction
                .jellybean_machine
                .expect("jellybean_machine is not set"),

            jellybean_machine_authority_pda: self
                .instruction
                .jellybean_machine_authority_pda
                .expect("jellybean_machine_authority_pda is not set"),

            payer: self.instruction.payer.expect("payer is not set"),

            buyer: self.instruction.buyer.expect("buyer is not set"),

            unclaimed_prizes: self
                .instruction
                .unclaimed_prizes
                .expect("unclaimed_prizes is not set"),

            print_fee_account: self.instruction.print_fee_account,

            spl_token_program: self
                .instruction
                .spl_token_program
                .expect("spl_token_program is not set"),

            system_program: self
                .instruction
                .system_program
                .expect("system_program is not set"),

            rent: self.instruction.rent.expect("rent is not set"),

            sysvar_instructions: self
                .instruction
                .sysvar_instructions
                .expect("sysvar_instructions is not set"),

            recent_slothashes: self
                .instruction
                .recent_slothashes
                .expect("recent_slothashes is not set"),

            jellybean_event_authority: self
                .instruction
                .jellybean_event_authority
                .expect("jellybean_event_authority is not set"),
            __args: args,
        };
        instruction.invoke_signed_with_remaining_accounts(
            signers_seeds,
            &self.instruction.__remaining_accounts,
        )
    }
}

#[derive(Clone, Debug)]
struct DrawJellybeanCpiBuilderInstruction<'a, 'b> {
    __program: &'b solana_account_info::AccountInfo<'a>,
    gumball_guard: Option<&'b solana_account_info::AccountInfo<'a>>,
    jellybean_machine_program: Option<&'b solana_account_info::AccountInfo<'a>>,
    jellybean_machine: Option<&'b solana_account_info::AccountInfo<'a>>,
    jellybean_machine_authority_pda: Option<&'b solana_account_info::AccountInfo<'a>>,
    payer: Option<&'b solana_account_info::AccountInfo<'a>>,
    buyer: Option<&'b solana_account_info::AccountInfo<'a>>,
    unclaimed_prizes: Option<&'b solana_account_info::AccountInfo<'a>>,
    print_fee_account: Option<&'b solana_account_info::AccountInfo<'a>>,
    spl_token_program: Option<&'b solana_account_info::AccountInfo<'a>>,
    system_program: Option<&'b solana_account_info::AccountInfo<'a>>,
    rent: Option<&'b solana_account_info::AccountInfo<'a>>,
    sysvar_instructions: Option<&'b solana_account_info::AccountInfo<'a>>,
    recent_slothashes: Option<&'b solana_account_info::AccountInfo<'a>>,
    jellybean_event_authority: Option<&'b solana_account_info::AccountInfo<'a>>,
    mint_args: Option<Vec<u8>>,
    group: Option<String>,
    /// Additional instruction accounts `(AccountInfo, is_writable, is_signer)`.
    __remaining_accounts: Vec<(&'b solana_account_info::AccountInfo<'a>, bool, bool)>,
}
